      if (err.message === 'MODEL_NOT_FOUND' || (err.message && err.message.includes('entity was not found'))) {
        alert("Lỗi kết nối AI (404). Vui lòng chọn lại API Key hợp lệ.");
        if ((window as any).aistudio?.openSelectKey) {
            await (window as any).aistudio.openSelectKey();
        }
      } else if (err.message === 'AI_QUOTA_EXCEEDED') {
        alert("Vui lòng thử lại sau.");
      } else {
        alert("Lỗi xử lý ảnh: " + (err.message || "Không xác định"));
      }
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  }, [settings, baseImage, getAiSettingsHash, config]); // Removed originalImage dependency

  const handleBgChange = (bg: BackgroundType) => onUpdateSettings({ ...settings, background: bg });
  const handleClothingClick = (prompt: string) => onUpdateSettings({ ...settings, clothingPrompt: prompt });
  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });

  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);
    let sepia = 0, hue = 0, saturate = 100;
    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) { sepia = skinToneIntensity * 0.3; saturate = 100 - (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.ROSY) { sepia = skinToneIntensity * 0.15; hue = -10; saturate = 100 + (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.FAIR) { saturate = 100 - (skinToneIntensity * 0.1); }
    }
    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  const handleFinish = () => {
    const finishExport = (imgSrc: string) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.src = imgSrc;
        img.onload = () => {
            canvas.width = img.width; canvas.height = img.height;
            if (ctx) { ctx.filter = imageFilters; ctx.drawImage(img, 0, 0, canvas.width, canvas.height); onProcessedImage(canvas.toDataURL('image/png', 1.0)); onNext(); }
        };
    };
    if (hasPendingAiChanges) {
        if (confirm("Có thay đổi chưa áp dụng. Áp dụng ngay?")) {
            handleApplyAiChanges().then(() => finishExport(processedUrl));
        } else { finishExport(processedUrl); }
    } else { finishExport(processedUrl); }
  };

  const startCrop = () => {
    setIsCropping(true);
  };

  const handleCropConfirm = (croppedImg: string) => {
    // 1. Set the new base image for AI to use
    setBaseImage(croppedImg); 
    // 2. Show the cropped image immediately
    setProcessedUrl(croppedImg);
    // 3. Reset hash to allow re-application of settings on the new crop
    setAppliedHash(''); 
    setIsCropping(false);
  };

  return (
    <div className="flex flex-col-reverse md:flex-row h-[100dvh] w-full bg-gray-100 dark:bg-gray-950 overflow-hidden font-sans pb-safe"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      {/* MANUAL CROPPER OVERLAY */}
      {isCropping && (
        <ManualCropper 
            imageSrc={processedUrl} // Crop the currently displayed image
            photoSize={settings.size}
            onCancel={() => setIsCropping(false)}
            onConfirm={handleCropConfirm}
        />
      )}

      {/* CONTROLS SIDEBAR */}
      <div className="w-full md:w-[420px] bg-white dark:bg-gray-900 shadow-[0_0_50px_rgba(0,0,0,0.15)] z-20 flex flex-col h-[55dvh] md:h-full border-t md:border-t-0 md:border-r border-gray-200 dark:border-gray-800 shrink-0">

        {/* Header */}
        <div className="hidden md:flex p-6 border-b border-gray-100 dark:border-gray-800 justify-between items-center shrink-0">
          <div className="flex flex-col">
              <h2 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Xử lý ảnh thẻ</h2>
              <span className="text-[10px] font-bold text-brand-600 uppercase tracking-widest mt-0.5">ID Photo Studio v2.5</span>
          </div>
          <button onClick={onRetake} className="text-xs font-bold text-red-500 hover:text-red-700 transition-colors flex items-center gap-1.5 uppercase tracking-wider">
             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg>
             Chụp lại
          </button>
        </div>

        {/* Tab Navigation */}
        <div className="px-4 pt-4 pb-2 md:px-6 md:pt-6 shrink-0 border-b border-gray-100 dark:border-gray-800 md:border-none overflow-x-auto scrollbar-hide">
          <div className="flex bg-gray-100 dark:bg-gray-800 p-1.5 rounded-2xl gap-1 min-w-max">
            {[
              {id: 'crop', label: 'Cắt ảnh', icon: '✂️'},
              {id: 'background', label: t('editor.tab.bg', config), icon: '🖼️'},
              {id: 'clothing', label: t('editor.tab.clothing', config), icon: '👔'},
              {id: 'makeup', label: t('editor.tab.makeup', config), icon: '✨'},
              {id: 'beauty', label: t('editor.tab.filter', config), icon: '🎨'}
            ].map((tab) => (
               <button 
                 key={tab.id} 
                 onClick={() => tab.id === 'crop' ? startCrop() : setActiveTab(tab.id as any)} 
                 className={`flex-1 px-4 flex flex-col items-center py-2.5 rounded-xl transition-all active:scale-95 ${
                    activeTab === tab.id && tab.id !== 'crop'
                    ? 'bg-white dark:bg-gray-700 text-brand-700 dark:text-brand-300 shadow-lg' 
                    : 'text-gray-500 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
                 }`}
               >
                 <span className="text-lg mb-0.5">{tab.icon}</span>
                 <span className="text-[10px] font-black uppercase tracking-tighter whitespace-nowrap">
                    {tab.label.includes('.') ? tab.label.split('.')[1] : tab.label}
                 </span>
               </button>
            ))}
          </div>
        </div>

        {/* Scrollable Controls Area */}
        <div className="flex-1 overflow-y-auto p-5 md:p-6 bg-white dark:bg-gray-900 scrollbar-hide">
          {activeTab === 'background' && (
            <EditorBackgroundTab config={config} settings={settings} onBgChange={handleBgChange} />
          )}

          {activeTab === 'clothing' && (
            <EditorClothingTab config={config} settings={settings} onClothingClick={handleClothingClick} />
          )}

          {activeTab === 'makeup' && (
            <EditorMakeupTab config={config} settings={settings} onAiBeautyChange={handleAiBeautyChange} />
          )}

          {activeTab === 'beauty' && (
            <EditorFilterTab settings={settings} onClientBeautyChange={handleClientBeautyChange} />
          )}
        </div>

        {/* Actions Footer */}
        <div className="p-4 md:p-6 border-t border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 space-y-3 shrink-0">
          {hasPendingAiChanges && (
            <button onClick={handleApplyAiChanges} disabled={isProcessing} className="w-full py-4 bg-brand-600 hover:bg-brand-700 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-brand-500/30 active:scale-95 disabled:opacity-50 flex items-center justify-center gap-3">
               {isProcessing ? <div className="w-5 h-5 border-2 border-white/50 border-t-white rounded-full animate-spin"></div> : "✨"} 
               {t('editor.btn.apply', config)}
            </button>
          )}
          <div className="flex gap-4">
            <button onClick={onRetake} className="flex-1 md:hidden py-4 bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-300 rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95">Chụp lại</button>
            <button onClick={handleFinish} disabled={isProcessing} className="flex-[3] py-4 bg-gray-900 dark:bg-brand-500 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl active:scale-95 disabled:bg-gray-400 transition-all">
               {t('editor.btn.finish', config)}
            </button>
          </div>
        </div>
      </div>

      {/* IMAGE PREVIEW AREA */}
      <div className="flex-1 bg-gray-200 dark:bg-gray-950 relative flex items-center justify-center p-6 md:p-12 h-[45dvh] md:h-full shrink-0">
        {isProcessing && (
          <div className="absolute inset-0 z-30 bg-black/40 backdrop-blur-md flex flex-col items-center justify-center">
            <div className="bg-white dark:bg-gray-900 p-8 rounded-[2.5rem] shadow-2xl flex flex-col items-center border border-white/10">
              <div className="w-12 h-12 border-4 border-brand-200 dark:border-brand-900 border-t-brand-600 dark:border-t-brand-400 rounded-full animate-spin mb-4"></div>
              <p className="text-gray-900 dark:text-white font-black text-xs uppercase tracking-widest">{loadingAction}</p>
            </div>
          </div>
        )}

        <div ref={imageContainerRef} className="relative shadow-[0_30px_100px_rgba(0,0,0,0.5)] rounded-lg border-8 border-white dark:border-gray-800 bg-white overflow-hidden max-h-full max-w-full cursor-col-resize touch-none"
             style={{ aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3', height: '100%', maxHeight: '100%' }}
             onMouseDown={() => { isDraggingRef.current = true; }}
             onTouchStart={() => { isDraggingRef.current = true; }}
             onMouseMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
             onTouchMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.touches[0].clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
        >
          {/* Compare View: Base (Cropped) vs Processed */}
          {/* Use baseImage here instead of originalImage so the comparison aligns correctly if cropped */}
          <img src={baseImage} className="absolute inset-0 w-full h-full object-contain pointer-events-none" />

          <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}>
             <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} />
          </div>

          <div className="absolute top-0 bottom-0 w-1 bg-white z-20 shadow-lg" style={{ left: `${sliderPosition}%` }}>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full shadow-2xl flex items-center justify-center border-4 border-brand-500 cursor-grab active:cursor-grabbing">
              <svg className="w-5 h-5 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M8 9l4-4 4 4m0 6l-4 4-4-4"></path></svg>
            </div>
          </div>

          <div className="absolute bottom-4 left-4 text-[9px] font-black text-white bg-black/50 px-3 py-1.5 rounded-full uppercase tracking-widest backdrop-blur-md pointer-events-none border border-white/10">Kết quả</div>
          <div className="absolute bottom-4 right-4 text-[9px] font-black text-white bg-brand-600/80 px-3 py-1.5 rounded-full uppercase tracking-widest backdrop-blur-md pointer-events-none border border-white/10">Ảnh gốc</div>
        </div>
      </div>
    </div>
  );
};

export default ImageEditor;

import React, { useEffect, useState } from 'react';
import { getPhotoById } from '../services/databaseService';
import { SavedPhoto, PhotoSize, AppConfig } from '../types';

interface PhotoViewerProps {
  photoId: string;
  config?: AppConfig; 
}

const PhotoViewer: React.FC<PhotoViewerProps> = ({ photoId, config }) => {
  const [photo, setPhoto] = useState<SavedPhoto | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  const getCurrentUrl = () => {
    return window.location.href;
  };

  useEffect(() => {
    const fetchPhoto = async () => {
      setLoading(true);
      try {
        const data = await getPhotoById(photoId);
        if (data) setPhoto(data);
        else setError('Không tìm thấy ảnh hoặc liên kết đã hết hạn.');
      } catch (e) {
        setError('Lỗi kết nối máy chủ.');
      } finally {
        setLoading(false);
      }
    };
    fetchPhoto();
  }, [photoId]);

  const downloadImage = (dataUrl: string, filename: string) => {
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadSingle = () => {
    if (!photo) return;
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = photo.dataUrl;
    img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(img, 0, 0);
            downloadImage(canvas.toDataURL('image/png'), `Photo-${photo.id}.png`);
        }
    };
  };

  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error(`Failed to load image`));
        img.src = src;
    });
  };

  const handleDownloadSheet = async () => {
    if (!photo) return;
    setIsGenerating(true);

    try {
        const DPI = 300;
        const MM_TO_PX = DPI / 25.4;
        const SHEET_W = Math.ceil(130 * MM_TO_PX);
        const SHEET_H = Math.ceil(180 * MM_TO_PX);

        const canvas = document.createElement('canvas');
        canvas.width = SHEET_W;
        canvas.height = SHEET_H;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error("Canvas init failed");

        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        const qrContent = getCurrentUrl();
        const qrApiUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(qrContent)}&ecc=H`;

        const [mainPhotoImg, logoImg, qrImg] = await Promise.all([
            loadImage(photo.dataUrl),
            config?.logoUrl ? loadImage(config.logoUrl).catch(() => null) : Promise.resolve(null),
            loadImage(qrApiUrl).catch(() => null)
        ]);

        const size = photo.settings.size;
        let cols=2, rows=4, photoW_mm=60, photoH_mm=40, rotated=true, maxOnSheet=8;

        if (size === PhotoSize.SIZE_3X4) {
            cols = 4; rows = 4; photoW_mm = 30; photoH_mm = 40; rotated = false; maxOnSheet = 16;
        } else if (size === PhotoSize.SIZE_5X5) {
            cols = 2; rows = 3; photoW_mm = 50; photoH_mm = 50; rotated = false; maxOnSheet = 6;
        }

        const cellW = photoW_mm * MM_TO_PX;
        const cellH = photoH_mm * MM_TO_PX;
        const startY = 5 * MM_TO_PX;
        const startX = (canvas.width - (cols * cellW)) / 2;

        for (let i = 0; i < maxOnSheet; i++) {
            const r = Math.floor(i / cols);
            const c = i % cols;
            const x = startX + c * cellW;
            const y = startY + r * cellH;
            ctx.save();
            ctx.beginPath();
            ctx.rect(x, y, cellW, cellH);
            ctx.clip();
            if (rotated) {
                ctx.translate(x + cellW/2, y + cellH/2);
                ctx.rotate(-90 * Math.PI / 180);
                ctx.drawImage(mainPhotoImg, -cellH/2, -cellW/2, cellH, cellW); 
            } else ctx.drawImage(mainPhotoImg, x, y, cellW, cellH);
            ctx.restore();
            ctx.strokeStyle = '#d1d5db';
            ctx.lineWidth = 1;
            ctx.setLineDash([15, 15]);
            ctx.strokeRect(x, y, cellW, cellH);
        }

        const footerH = 15 * MM_TO_PX;
        const footerY = canvas.height - footerH;
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, footerY, canvas.width, footerH);
        ctx.beginPath(); ctx.moveTo(0, footerY); ctx.lineTo(canvas.width, footerY);
        ctx.strokeStyle = '#000000'; ctx.lineWidth = 2; ctx.setLineDash([]); ctx.stroke();

        let leftOffset = 5 * MM_TO_PX;
        if (logoImg) {
            const logoH = 10 * MM_TO_PX;
            const logoW = logoImg.width * (logoH / logoImg.height);
            ctx.drawImage(logoImg, leftOffset, footerY + 2.5 * MM_TO_PX, logoW, logoH);
            leftOffset += logoW + 3 * MM_TO_PX;
        }

        ctx.fillStyle = '#000000';
        ctx.font = `bold ${5 * MM_TO_PX}px sans-serif`;
        ctx.textBaseline = 'middle';
        ctx.fillText(config?.shopName || "ID Photo Booth", leftOffset, footerY + 7.5 * MM_TO_PX);

        if (qrImg) ctx.drawImage(qrImg, canvas.width - 17 * MM_TO_PX, footerY + 1.5 * MM_TO_PX, 12 * MM_TO_PX, 12 * MM_TO_PX);

        downloadImage(canvas.toDataURL('image/png'), `Photo-${photo.id}-PrintSheet.png`);
    } catch (e) {
        alert("Lỗi tạo file in.");
    } finally {
        setIsGenerating(false);
    }
  };

  if (loading) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-white dark:bg-gray-950 p-6">
        <div className="w-16 h-16 border-4 border-brand-100 border-t-brand-600 rounded-full animate-spin mb-6"></div>
        <p className="text-gray-500 dark:text-gray-400 font-bold animate-pulse uppercase tracking-widest text-xs">Đang tải ảnh của bạn...</p>
    </div>
  );

  if (error || !photo) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-gray-950 p-6 text-center">
        <div className="w-20 h-20 bg-red-50 dark:bg-red-900/20 text-red-500 rounded-full flex items-center justify-center mb-6 shadow-xl">
            <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
        </div>
        <h2 className="text-2xl font-black text-gray-900 dark:text-white mb-2 uppercase">Lỗi truy cập</h2>
        <p className="text-gray-500 dark:text-gray-400 mb-8 max-w-xs mx-auto text-sm">{error}</p>
        <a href="/" className="px-8 py-3 bg-brand-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-brand-500/30 active:scale-95 transition-all">Về trang chủ</a>
    </div>
  );

  return (
    <div className="min-h-[100dvh] bg-gray-50 dark:bg-gray-950 flex flex-col font-sans">

       {/* Transparent Sticky Header */}
       <header className="sticky top-0 z-30 w-full bg-white/70 dark:bg-gray-900/70 backdrop-blur-xl border-b border-gray-200 dark:border-gray-800 px-6 py-4">
          <div className="max-w-5xl mx-auto flex items-center justify-between">
             <div className="flex items-center gap-3">
                {config?.logoUrl ? (
                   <img src={config.logoUrl} alt="Logo" className="h-8 w-auto object-contain" />
                ) : (
                   <div className="w-8 h-8 bg-brand-600 rounded-xl flex items-center justify-center text-white font-black text-sm">
                     {config?.shopName?.charAt(0) || 'P'}
                   </div>
                )}
                <span className="font-black text-sm text-gray-900 dark:text-white uppercase tracking-tight">{config?.shopName || 'ID Photo Booth'}</span>
             </div>
             <div className="text-[10px] font-black text-brand-600 bg-brand-50 dark:bg-brand-900/30 px-3 py-1 rounded-full uppercase tracking-widest border border-brand-100 dark:border-brand-800">Ảnh đã sẵn sàng</div>
          </div>
       </header>

       {/* Main Content Area */}
       <main className="flex-1 max-w-5xl w-full mx-auto p-4 md:p-8 grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

          {/* Left: Interactive Photo Preview (Lg: Col 7) */}
          <div className="lg:col-span-7 space-y-6">
             <div className="bg-white dark:bg-gray-900 rounded-[2.5rem] p-6 md:p-10 shadow-2xl shadow-gray-200/50 dark:shadow-black/50 border border-gray-100 dark:border-gray-800 flex flex-col items-center group">
                <div className="relative inline-block">
                   <div className="absolute -inset-4 bg-gradient-to-tr from-brand-500 to-purple-500 rounded-3xl blur-2xl opacity-10 group-hover:opacity-20 transition-opacity"></div>
                   <div className="relative shadow-[0_20px_60px_-15px_rgba(0,0,0,0.3)] rounded-xl overflow-hidden border-[6px] border-white dark:border-gray-800 bg-white dark:bg-gray-800 transition-transform duration-500 group-hover:scale-[1.02]">
                       <img 
                         src={photo.dataUrl} 
                         className="max-h-[50vh] md:max-h-[60vh] w-auto object-contain" 
                         alt="ID Photo Result" 
                       />
                   </div>
                </div>

                <div className="mt-8 flex gap-3">
                   <div className="px-4 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-2xl text-[10px] font-black text-gray-500 dark:text-gray-400 uppercase tracking-widest">
                      Kích thước: {photo.settings.size}
                   </div>
                   <div className="px-4 py-2 bg-gray-50 dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-2xl text-[10px] font-black text-gray-500 dark:text-gray-400 uppercase tracking-widest">
                      {new Date(photo.timestamp).toLocaleDateString('vi-VN')}
                   </div>
                </div>
             </div>

             {/* Help Note for Mobile */}
             <div className="bg-blue-50/50 dark:bg-blue-900/10 p-5 rounded-3xl border border-blue-100 dark:border-blue-800 flex gap-4">
                <div className="text-2xl">💡</div>
                <p className="text-xs text-blue-800 dark:text-blue-300 leading-relaxed font-medium">
                   <b>Lưu ý:</b> Bạn nên tải "Ảnh Thẻ Đơn" để lưu giữ trên điện thoại và "File In Sheet" nếu muốn mang ra tiệm in ấn chuyên nghiệp.
                </p>
             </div>
          </div>

          {/* Right: Actions & QR (Lg: Col 5) */}
          <div className="lg:col-span-5 space-y-6">
             <div className="bg-white dark:bg-gray-900 rounded-[2.5rem] p-8 shadow-2xl shadow-gray-200/50 dark:shadow-black/50 border border-gray-100 dark:border-gray-800 space-y-5">
                <h2 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight text-center lg:text-left">Tải ảnh xuống</h2>

                {/* Download Single Card */}
